// Generated by `just generate` from `src/plugins/claudetto-sessions/slices/awareness/lab/awareness.test.ts`. Edit the source and run `just generate`.
// The hook lab of the `awareness` slice: `claude plugin test plugins/claudetto-sessions` fires `session.measure`, `tool.call`, and `session.start` with stubs.
// No session starts and no model call goes out.

import type { On } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

type Window = { kind: string; percentUsed: number };

/** The stubs of one test: the bottom of each chain, and the lines of the debug log and of the transcript. */
const stub = (on: On) => {
  const seen = { debug: [] as string[], appended: [] as unknown[] };
  on("session.measure", (_$, e) => ({ changed: e.changed }));
  on("session.start", (_$, e) => ({ cwd: e.cwd }));
  on("tool.call", () => ({ result: "ok", context: ["other"] }));
  on("ui.log", (_$, e) => {
    seen.debug.push(e.text);
    return { value: undefined };
  });
  on("session.append", (_$, e) => {
    seen.appended.push(e);
    return { ok: true } as never;
  });
  return seen;
};

const measure = ($: Engine, percentUsed: number, kind = "seven_day") => {
  const rateLimits: Window[] = [{ kind, percentUsed }];
  return $.session.measure({
    context: {} as never,
    rateLimits,
    changed: ["rateLimits"],
  });
};

const callEdit = ($: Engine, agentId?: string) =>
  $.tool.call({
    tool: "Edit",
    file_path: "/p/a.txt",
    old_string: "a",
    new_string: "b",
    ...(agentId === undefined ? {} : { agentId }),
  });

test("a weekly share below the bound makes no note", async ($: Engine, on: On) => {
  stub(on);
  await measure($, 79.9);
  await measure($, 95, "five_hour");
  expect((await callEdit($)).context).toStrictEqual(["other"]);
});

// biome-ignore lint/plugin: the test name is kept whole, because the `slice.ts` file references it
test("a weekly share at the bound makes one note, and a handler error does not stop the session", async ($: Engine, on: On) => {
  const seen = stub(on);
  const out = await measure($, 80);
  expect(out.changed).toStrictEqual(["rateLimits"]);
  await measure($, 90);
  const first = await callEdit($);
  expect(first.context).toStrictEqual([
    "other",
    expect.stringContaining("80 percent"),
  ]);
  expect((await callEdit($)).context).toStrictEqual(["other"]);
  expect(seen.debug).toStrictEqual([]);
  // A reading with no list of windows breaks the handler: the hook logs it and the chain goes on.
  const after = await $.session.measure({
    context: {} as never,
    rateLimits: undefined as never,
    changed: ["rateLimits"],
  });
  expect(after.changed).toStrictEqual(["rateLimits"]);
  expect(seen.debug.join("\n")).toContain("claudetto-sessions: TypeError");
});

test("a subagent's call takes no note", async ($: Engine, on: On) => {
  stub(on);
  await measure($, 90);
  expect((await callEdit($, "agent-1")).context).toStrictEqual(["other"]);
  expect((await callEdit($)).context).toStrictEqual([
    "other",
    expect.stringContaining("90 percent"),
  ]);
});

test("the main agent gets the note once", async ($: Engine, on: On) => {
  stub(on);
  await measure($, 81);
  const notes = (await callEdit($)).context ?? [];
  expect(notes.filter((n) => n.includes("seven-day"))).toHaveLength(1);
  const again = (await callEdit($)).context ?? [];
  expect(again.filter((n) => n.includes("seven-day"))).toHaveLength(0);
});

test("a session start writes no stamp into the transcript", async ($: Engine, on: On) => {
  const seen = stub(on);
  await $.session.start({ cwd: "/p", surface: null, isInteractive: false });
  expect(seen.appended).toStrictEqual([]);
  expect(
    seen.debug.filter((line) => line.trimStart().startsWith("{")),
  ).toStrictEqual([]);
});
